using System.Text.Json;using Confluent.Kafka;using Medzo.CatalogueInventory.Application.Common;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;
namespace Medzo.CatalogueInventory.Infrastructure.Messaging;
public sealed class StockEventConsumer(IServiceScopeFactory scopes,IConfiguration configuration,ILogger<StockEventConsumer> log):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken ct){var config=new ConsumerConfig{BootstrapServers=configuration["Kafka:BootstrapServers"]??"localhost:9092",GroupId=configuration["Kafka:ConsumerGroup"]??"medzo-catalogue-inventory-v1",EnableAutoCommit=false,AutoOffsetReset=AutoOffsetReset.Earliest};using var consumer=new ConsumerBuilder<string,string>(config).Build();consumer.Subscribe(["purchasing.purchase-recorded.v1","sales.sale-completed.v1"]);while(!ct.IsCancellationRequested){try{var result=consumer.Consume(ct);var envelope=JsonSerializer.Deserialize<EventEnvelope>(result.Message.Value,new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new JsonException("Event is empty.");using var scope=scopes.CreateScope();var service=scope.ServiceProvider.GetRequiredService<IInventoryService>();var message=new ExternalStockEvent(envelope.EventId,envelope.Data.SourceId,envelope.OccurredAtUtc,envelope.Data.Lines);if(result.Topic=="purchasing.purchase-recorded.v1")await service.ApplyPurchaseAsync(message,ct);else await service.ApplySaleAsync(message,ct);consumer.Commit(result);}catch(OperationCanceledException)when(ct.IsCancellationRequested){break;}catch(Exception e){log.LogError(e,"Kafka event processing failed; the offset will be retried.");await Task.Delay(TimeSpan.FromSeconds(5),ct);}}consumer.Close();}
 private sealed record EventEnvelope(Guid EventId,DateTime OccurredAtUtc,EventData Data);private sealed record EventData(string SourceId,IReadOnlyList<ExternalStockLine> Lines);
}
